-- 2) Zaaps (modèle 16) sans action : relier l'action partagée ZaapTeleport (interactives_skills Id 1), comme 07_zaaps.sql.
INSERT IGNORE INTO interactives_skills (Id, Type, Duration, `Condition`, CustomTemplateId)
 SELECT 1, 'ZaapTeleport', 0, '', 114 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM interactives_skills WHERE Id = 1);
INSERT IGNORE INTO interactives_spawns_skills (Id, InteractiveSpawnId, SkillId)
 SELECT 4000000 + s.Id, s.Id, 1 FROM interactives_spawns s
 WHERE s.TemplateId = 16 AND NOT EXISTS (SELECT 1 FROM interactives_spawns_skills ss WHERE ss.InteractiveSpawnId = s.Id);
-- le zaap côtier précisément (517181, map 164364304 case 271) : modèle Zaap + action, même s'il avait été modifié
UPDATE interactives_spawns SET TemplateId = 16, Animated = 1 WHERE Id = 517181;
INSERT IGNORE INTO interactives_spawns_skills (Id, InteractiveSpawnId, SkillId)
 SELECT 4517181, 517181, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM interactives_spawns_skills WHERE InteractiveSpawnId = 517181 AND SkillId = 1);

-- 3) Contrôle (à lire dans Navicat) : attendu porte_labo = 1, zaap_cotier >= 1, zaaps_sans_action = 0, portes_animees >= 608
SELECT (SELECT Animated FROM interactives_spawns WHERE Id = 482705) AS porte_labo,
       (SELECT COUNT(*) FROM interactives_spawns_skills WHERE InteractiveSpawnId = 517181 AND SkillId = 1) AS zaap_cotier,
       (SELECT COUNT(*) FROM interactives_spawns s WHERE s.TemplateId = 16 AND NOT EXISTS (SELECT 1 FROM interactives_spawns_skills k WHERE k.InteractiveSpawnId = s.Id)) AS zaaps_sans_action,
       (SELECT COUNT(*) FROM interactives_spawns WHERE TemplateId = 0 AND Animated = 1) AS portes_animees;
